        if (Style.StGet(sf, l, Style.SfkCps()) < 1) {
            return 0;
        }
        int sib = Style.StGet(sf, l, Style.SfkSib());
        int cps = Style.StGet(sf, l, Style.SfkCps());
        int f = Style.StGet(sf, l, Style.SfkFirst());
        // a row sibling: a table cell, an initial's neighbour (D108); but the two halves of one heading line are not
        int pq = HdPartner(wd, ln, et, ws, sf, l);
        int nsib = Style.StGet(sf, l, Style.SfkNsib());
        int sl = Style.StGet(sf, l, Style.SfkSibline());
        if (pq < 0) {
            // beside something that is not a column of body text: a table cell, a label and its value
            // (a headline set a fifth bigger than the body is not a table cell, whatever is beside it: a column's)
            if ((nsib > Style.StGet(sf, l, Style.SfkNcol())) && ((Style.StGet(sf, l, Style.SfkSize()) * 100) < (Style.StHget(sf, Style.SfhSize()) * 120))) {
                return 0;
            }
            // an initial: one or two code points with anything beside it; a divider has nothing on its row
            if ((cps <= 2) && (nsib > 0)) {
                return 0;
            }
            // an initial WORD (D108): a short single word, near the body text it starts, much taller than it,
            // and that text goes on in lower case. P4.10 finds initials properly; this keeps one from being a heading.
            if ((nsib > 0) && ((Style.StGet(sf, l, Style.SfkWords()) == 1) && ((cps <= 12) && (((sib & 4) != 0) && (sl >= 0))))) {
                if ((Style.StGet(sf, l, Style.SfkHeight()) >= (2 * Style.StGet(sf, sl, Style.SfkHeight()))) && Style.StLower(Style.StGet(sf, sl, Style.SfkFirst()))) {
                    return 0;
                }
            }
            if ((Style.StGet(sf, l, Style.SfkLetters()) == 0) && (f < 128)) {
                return 0;
            }
        }
        if (HdBullet(f) == 1) {
            return 0;
        }
        int ps = HdStylePoints(sf, sc, l);
        if (ps < 0) {
            return 0;
        }
        if (ps == 0) {
            if (HdMarker(wd, ln, et, ws, l) == 0) {
                return 0;
            }
        }
        HdPutHead(sf, l, 1, ps);
        return 1;
    }
    internal static bool HdSentenceEnd(int c) {
        // A mark that closes a sentence or a clause: a heading does not end in one.
        return (c == 46) || ((c == 44) || ((c == 59) || ((c == 33) || ((c == 63) || ((c == 8230) || ((c == 12290) || ((c == 65281) || ((c == 65311) || ((c == 65292) || (c == 65294))))))))));
    }
    internal static int HdTight(emon.Port.Cells sf, int a, int b) {
        // Is line b right below line a, as close as the lines of one heading: within 3/2 of the document's line gap
        // and a quarter of b's size.
        if (Style.StGet(sf, b, Style.SfkAbove()) != a) {
            return 0;
        }
        int g = Style.StGet(sf, b, Style.SfkGapAbove());
        int lim = ((Style.StHget(sf, Style.SfhGap()) * 3) / 2) + (Style.StGet(sf, b, Style.SfkSize()) / 4);
        if (g <= lim) {
            return 1;
        }
        return 0;
    }
    internal static int HdUn(emon.Port.Cells ws, int u, int f) {
        return emon.Port.CellsAt(ws, (WsU + (u * UnStride)) + f);
    }
    internal static int HdUnSet(emon.Port.Cells ws, int u, int f, int v) {
        emon.Port.CellsSet(ws, (WsU + (u * UnStride)) + f, v);
        return 0;
    }
    internal static int HdAbs(int v) {
        if (v < 0) {
            return 0 - v;
        }
        return v;
    }
    internal static int HdFold(int c) {
        // A code point for comparing titles: ASCII and Latin-1 capitals fold to lower case.
        if ((c >= 65) && (c <= 90)) {
            return c + 32;
        }
        if ((c >= 192) && ((c <= 222) && (c != 215))) {
            return c + 32;
        }
        return c;
    }
    internal static int HdTextHash(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells ws, int cnt) {
        // A hash of the unit's text with its digits and its case left out, so the running header of a document
        // (`Page 3 of 10`, `September 2024`, a title that carries a page number) is one value on every page.
        int h = 7;
        int i = 0;
        int k = 0;
        int j = 0;
        while (i < cnt) {
            int l = emon.Port.CellsAt(ws, WsLines + i);
            int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
            int wn = Evidence.LnGet(ln, l, Evidence.LhCount());
            k = 0;
            while (k < wn) {
                int tl = HdWl(wd, w0 + k);
                j = 0;
                while (j < tl) {
                    int c = HdWc(wd, et, w0 + k, j);
                    if ((c < 48) || (c > 57)) {
                        h = ((h * 31) + HdFold(c)) % 1000003;
                    }
                    j += 1;
                }
                k += 1;
            }
            i += 1;
        }
        return h;
    }
    internal static int HdSpacing(emon.Port.Cells sf, int top, int last) {
        // The whitespace around a heading, in points of evidence: 0 as tight as body lines, 1 more, 2 well apart;
        // +1 when there is more space above than below; a heading with nothing above it (the top of a page, or
        // under a figure) gets 1.
        int lg = Style.StHget(sf, Style.SfhGap());
        int sz = Style.StGet(sf, top, Style.SfkSize());
        int ab = Style.StGet(sf, top, Style.SfkAbove());
        int ga = Style.StGet(sf, top, Style.SfkGapAbove());
        int p = 0;
        if (ab < 0) {
            p = 1;
        } else {
            if (ga >= ((lg * 2) + (sz / 4))) {
                p = 2;
            } else if ((ga * 8) > ((lg * 10) + sz)) {
                p = 1;
            }
            if (Style.StGet(sf, last, Style.SfkBelow()) >= 0) {
                if ((ga - Style.StGet(sf, last, Style.SfkGapBelow())) > (sz / 8)) {
                    p += 1;
                }
            }
        }
        return p;
    }
    internal static int HdListRun(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells ws, emon.Port.Cells sf, int top, int last) {
        // Is a body-styled numbered line one of a numbered run: a neighbour above or below it with the same class
        // and a numbering pattern of its own. Then it is a list item, not a heading (SPEC 10.4).
        int a = Style.StGet(sf, top, Style.SfkAbove());
        int b = Style.StGet(sf, last, Style.SfkBelow());
        int c = Style.StGet(sf, top, Style.SfkClass());
        if ((a >= 0) && ((Style.StGet(sf, a, Style.SfkClass()) == c) && (Style.StGet(sf, a, Style.SfkHead()) == 1))) {
            return 1;
        }
        if ((b >= 0) && ((Style.StGet(sf, b, Style.SfkClass()) == c) && (Style.StGet(sf, b, Style.SfkHead()) == 1))) {
            return 1;
        }
        return 0;
    }
    internal static int HdUnitScore(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells ws, emon.Port.Cells sf, emon.Port.Cells sc, int cnt) {
        // The score of the unit whose lines are ws[WS_LINES..]: -1 when it cannot be a heading. Leaves the
        // numbering of its first line in ws[0..4].
        int top = emon.Port.CellsAt(ws, WsLines);
        int last = emon.Port.CellsAt(ws, WsLines + (cnt - 1));
        int ps = Style.StGet(sf, top, Style.SfkPoints());
        int body = Style.StHget(sf, Style.SfhBody());
        int total = 0;
        int i = 0;
        int s = 0;
        int pts = 0;
        while (i < cnt) {
            total += Style.StGet(sf, emon.Port.CellsAt(ws, WsLines + i), Style.SfkCps());
            i += 1;
        }
        if (total > HdMaxcps) {
            return -1;
        }
        if (HdSentenceEnd(Style.StGet(sf, last, Style.SfkLast()))) {
            return -1;
        }
        if (ps == 0) {
            if (HdListRun(wd, ln, et, ws, sf, top, last) == 1) {
                return -1;
            }
        }
        s = HdMarker(wd, ln, et, ws, top);
        pts = ps;
        if (s > 0) {
            if (((s == 1) || ((s == 6) || (s == 7))) && (emon.Port.CellsAt(ws, 1) >= 2)) {
                pts += 4;
            } else {
                pts += 2;
            }
        }
        int sp = HdSpacing(sf, top, last);
        int lg = Style.StHget(sf, Style.SfhGap());
        int sz = Style.StGet(sf, top, Style.SfkSize());
        int b = Style.StGet(sf, last, Style.SfkBelow());
        int gb = Style.StGet(sf, last, Style.SfkGapBelow());
        if ((ps == 0) && (sp < 1)) {
            return -1;
        }
        // a body-styled numbered line followed at the body's own line gap is a paragraph or a list item
        if ((ps == 0) && ((b >= 0) && ((gb * 2) < (lg * 3)))) {
            return -1;
        }
        // smaller than the body, so it is the weight or the capitals alone that says heading: it must at least
        // be followed by text close by, or be numbered (a label inside a seal or a figure is neither)
        if (((sz * 100) <= (Style.StHget(sf, Style.SfhSize()) * 96)) && (s == 0)) {
            if ((b < 0) || (gb > ((lg * 5) + sz))) {
                return -1;
            }
        }
        pts += sp;
        if ((b >= 0) && (Style.StGet(sf, b, Style.SfkClass()) == body)) {
            pts += 1;
        }
        if (total <= 80) {
            pts += 1;
        }
        if (cnt >= 3) {
            pts -= 1;
        }
        // a line that ends in a figure is a label and its value (`Opening balance 4,210.55`), unless it is numbered
        int lc = Style.StGet(sf, last, Style.SfkLast());
        if ((s == 0) && ((lc >= 48) && (lc <= 57))) {
            pts -= 2;
        }
        // italic or another colour alone, with no number: an emphasised line more often than a heading
        if ((s == 0) && (ps <= 1)) {
            pts -= 2;
        }
        return pts;
    }
    internal static int HdCollect(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells ws, emon.Port.Cells sf, emon.Port.Cells sc, int n) {
        // Group the candidate lines into units (a heading that wraps is one unit), score them, keep the ones
        // that reach HD_MIN. Units are rows from WS_U. Answers their number.
        int l = 0;
        int nu = 0;
        int cur = 0;
        int more = 0;
        int cnt = 0;
        int k = 0;
        int steps = 0;
        int sco = 0;
        int pairflag = 0;
        int nb = 0;
        while (l < n) {
            if ((Style.StGet(sf, l, Style.SfkHead()) == 1) && (Style.StGet(sf, l, Style.SfkUnit()) == -1)) {
                // climb to the top of the run of candidate lines of one class
                cur = l;
                more = 1;
                steps = 0;
                while ((more == 1) && (steps < HdMaxlines)) {
                    nb = Style.StGet(sf, cur, Style.SfkAbove());
                    if ((nb >= 0) && ((Style.StGet(sf, nb, Style.SfkHead()) == 1) && ((Style.StGet(sf, nb, Style.SfkUnit()) == -1) && ((Style.StGet(sf, nb, Style.SfkClass()) == Style.StGet(sf, cur, Style.SfkClass())) && ((HdTight(sf, nb, cur) == 1) && (HdMarker(wd, ln, et, ws, cur) == 0)))))) {
                        cur = nb;
                    } else {
                        more = 0;
                    }
                    steps += 1;
                }
                // the two halves of one heading line (a number and its title on one row): the number first
                emon.Port.CellsSet(ws, WsLines, cur);
                cnt = 1;
                pairflag = 0;
                nb = HdPartner(wd, ln, et, ws, sf, cur);
                if ((nb >= 0) && ((Style.StGet(sf, nb, Style.SfkHead()) == 1) && (Style.StGet(sf, nb, Style.SfkUnit()) == -1))) {
                    pairflag = 1;
                    if (HdMarkerOnly(wd, ln, et, ws, cur) == 1) {
                        emon.Port.CellsSet(ws, WsLines + 1, nb);
                        cur = nb;
                    } else {
                        emon.Port.CellsSet(ws, WsLines, nb);
                        emon.Port.CellsSet(ws, WsLines + 1, cur);
                    }
                    cnt = 2;
                }
                // and walk down it
                more = 1;
                while ((more == 1) && (cnt <= HdMaxlines)) {
                    nb = Style.StGet(sf, cur, Style.SfkBelow());
                    if ((nb >= 0) && ((Style.StGet(sf, nb, Style.SfkHead()) == 1) && ((Style.StGet(sf, nb, Style.SfkUnit()) == -1) && ((Style.StGet(sf, nb, Style.SfkClass()) == Style.StGet(sf, emon.Port.CellsAt(ws, WsLines), Style.SfkClass())) && ((HdTight(sf, cur, nb) == 1) && (HdMarker(wd, ln, et, ws, nb) == 0)))))) {
                        emon.Port.CellsSet(ws, WsLines + cnt, nb);
                        cnt += 1;
                        cur = nb;
                    } else {
                        more = 0;
                    }
                }
                sco = -1;
                if (cnt <= HdMaxlines) {
                    sco = HdUnitScore(wd, ln, et, ws, sf, sc, cnt);
                }
                if (sco >= HdMin) {
                    int top = emon.Port.CellsAt(ws, WsLines);
                    int u = WsU + (nu * UnStride);
                    while (emon.Port.CellsLen(ws) < (u + UnStride)) {
                        emon.Port.CellsPush(ws, 0);
                    }
                    HdUnSet(ws, nu, 0, top);
                    HdUnSet(ws, nu, 1, emon.Port.CellsAt(ws, WsLines + (cnt - 1)));
                    HdUnSet(ws, nu, 2, cnt);
                    HdUnSet(ws, nu, 3, -1);
                    HdUnSet(ws, nu, 4, sco);
                    HdUnSet(ws, nu, 5, emon.Port.CellsAt(ws, 0));
                    HdUnSet(ws, nu, 6, emon.Port.CellsAt(ws, 1));
                    HdUnSet(ws, nu, 7, emon.Port.CellsAt(ws, 2));
                    HdUnSet(ws, nu, 8, emon.Port.CellsAt(ws, 3));
                    HdUnSet(ws, nu, 9, emon.Port.CellsAt(ws, 4));
                    if (pairflag == 1) {
                        int ncps = Style.StGet(sf, top, Style.SfkCps());
                        HdUnSet(ws, nu, 9, ncps + 1);
                    }
                    HdUnSet(ws, nu, 10, Style.StGet(sf, top, Style.SfkPage()));
                    HdUnSet(ws, nu, 11, Evidence.LnGet(ln, top, Evidence.LhY0()));
                    HdUnSet(ws, nu, 12, Style.StGet(sf, top, Style.SfkX0()));
                    HdUnSet(ws, nu, 13, 0);
                    HdUnSet(ws, nu, 14, 0);
                    int hh = HdTextHash(wd, ln, et, ws, cnt);
                    HdUnSet(ws, nu, 15, hh);
                    k = 0;
                    while (k < cnt) {
                        Style.StSet(sf, emon.Port.CellsAt(ws, WsLines + k), Style.SfkUnit(), nu);
                        k += 1;
                    }
                    nu += 1;
                } else {
                    k = 0;
                    while (k < cnt) {
                        Style.StSet(sf, emon.Port.CellsAt(ws, WsLines + k), Style.SfkUnit(), -2);
                        k += 1;
                    }
                }
            }
            l += 1;
        }
        emon.Port.CellsSet(ws, WsVar, nu);
        return nu;
    }
    internal static int HdRecurs(emon.Port.Cells ws, int u, int nu) {
        // Is the unit a running header or footer: the same text (digits aside) at the same place on at least two
        // other pages. SPEC 10.2 does this properly (P4.3); a heading is never that, and a document's running
        // title must not be taken for its headings meanwhile. 1 = yes.
        int v = 0;
        int same = 0;
        int dy = 0;
        int dx = 0;
        while (v < nu) {
            if ((v != u) && ((HdUn(ws, v, 15) == HdUn(ws, u, 15)) && (HdUn(ws, v, 10) != HdUn(ws, u, 10)))) {
                dy = HdAbs(HdUn(ws, v, 11) - HdUn(ws, u, 11));
                dx = HdAbs(HdUn(ws, v, 12) - HdUn(ws, u, 12));
                if ((dy < 300) && (dx < 300)) {
                    same += 1;
                }
            }
            v += 1;
        }
        if (same >= 2) {
            return 1;
        }
        return 0;
    }
    internal static int HdLone(emon.Port.Cells ws, emon.Port.Cells sf, int u, int nu) {
        // A unit numbered by a letter or a roman numeral (or a keyword and a letter) that is the only one of its
        // style and scheme: a sequence is what a letter marker is evidence of, and `A. Author` is a name. 1 = lone.
        int s = HdUn(ws, u, 5);
        int sclass = Style.StGet(sf, HdUn(ws, u, 0), Style.SfkClass());
        int v = 0;
        int same = 0;
        if ((s >= 2) && (s <= 5)) {
            while (v < nu) {
                if ((HdUn(ws, v, 5) == s) && (Style.StGet(sf, HdUn(ws, v, 0), Style.SfkClass()) == sclass)) {
                    same += 1;
                }
                v += 1;
            }
            if (same < 2) {
                return 1;
            }
        }
        return 0;
    }
    internal static int HdKicker(emon.Port.Cells ws, emon.Port.Cells sf, int u, int nu) {
        // A masthead, letterhead or kicker: an unnumbered unit set directly above a unit of a clearly larger size
        // (no text between them, one page), where both are one-offs: each of the two styles is set once in the
        // document. What stands over the title is the publisher's name or the series, not a section of the
        // document. A title above recurring heads that print larger (letter dividers) is a title: the larger
        // style recurs, so it is a rank of the document's own. 1 = a kicker.
        if ((u + 1) < nu) {
            int last = HdUn(ws, u, 1);
            int nxt = HdUn(ws, u + 1, 0);
            int sz = Style.StGet(sf, HdUn(ws, u, 0), Style.SfkSize());
            int cu = Style.StGet(sf, HdUn(ws, u, 0), Style.SfkClass());
            int cn = Style.StGet(sf, nxt, Style.SfkClass());
            int v = 0;
            if ((HdUn(ws, u, 5) == 0) && ((Style.StGet(sf, last, Style.SfkBelow()) == nxt) && ((HdUn(ws, u, 10) == HdUn(ws, u + 1, 10)) && ((Style.StGet(sf, nxt, Style.SfkSize()) * 100) > (sz * KickerRatio))))) {
                while (v < nu) {
                    if ((v != u) && (v != (u + 1))) {
                        if ((Style.StGet(sf, HdUn(ws, v, 0), Style.SfkClass()) == cu) || (Style.StGet(sf, HdUn(ws, v, 0), Style.SfkClass()) == cn)) {
                            return 0;
                        }
                    }
                    v += 1;
                }
                return 1;
            }
        }
        return 0;
    }
    internal static int HdDropLone(emon.Port.Cells ws, emon.Port.Cells sf, int n) {
        // Remove the lone letter-numbered units (`hd-lone`) from the table and from the lines. Answers how many
        // units are left.
        int nu = emon.Port.CellsAt(ws, WsVar);
        int @base = emon.Port.CellsLen(ws);
        int u = 0;
        int w = 0;
        int f = 0;
        int l = 0;
        if (nu > 2000) {
            return nu;
        }
        while (u < nu) {
            if ((HdLone(ws, sf, u, nu) == 1) || ((HdRecurs(ws, u, nu) == 1) || (HdKicker(ws, sf, u, nu) == 1))) {
                emon.Port.CellsPush(ws, -2);
            } else {
                emon.Port.CellsPush(ws, w);
                w += 1;
            }
            u += 1;
        }
        u = 0;
        while (u < nu) {
            int to = emon.Port.CellsAt(ws, @base + u);
            if (to >= 0) {
                f = 0;
                while (f < UnStride) {
                    int cell = HdUn(ws, u, f);
                    HdUnSet(ws, to, f, cell);
                    f += 1;
                }
            }
            u += 1;
        }
        l = 0;
        while (l < n) {
            int id = Style.StGet(sf, l, Style.SfkUnit());
            if (id >= 0) {
                Style.StSet(sf, l, Style.SfkUnit(), emon.Port.CellsAt(ws, @base + id));
            }
            l += 1;
        }
        emon.Port.CellsDrop(ws, WsU + (w * UnStride));
        emon.Port.CellsSet(ws, WsVar, w);
        return w;
    }
    public static int HdPriorAdd(emon.Port.Cells pr, emon.Port.Cells ptxt, int src, int tstart, int tlen, emon.Port.Cells from, int level, int weight) {
        // One external prior: the heading text from[tstart..tstart+tlen), the level it says (1..), its source (1
        // tagged, 2 outline) and its weight per-mille (a tagged tree's trust, D034; an outline's 800). Rows of
        // `pr` are (text start in `ptxt`, length, level, source, weight).
        int at = emon.Port.CellsLen(ptxt);
        int i = 0;
        while (i < tlen) {
            emon.Port.CellsPush(ptxt, emon.Port.CellsAt(from, tstart + i));
            i += 1;
        }
        emon.Port.CellsPush(pr, at);
        emon.Port.CellsPush(pr, tlen);
        emon.Port.CellsPush(pr, level);
        emon.Port.CellsPush(pr, src);
        emon.Port.CellsPush(pr, weight);
        return emon.Port.CellsLen(pr) / 5;
    }
    public static int HdPriorOutline(emon.Port.Cells ol, emon.Port.Cells txt, emon.Port.Cells pr, emon.Port.Cells ptxt) {
        // Every row of P3.9's outline (`ol`, 24 cells a row: depth, ..., title run at 5 and 6 of `txt`) as a
        // prior: level depth + 1, weight 800. Answers the number of rows read.
        int n = emon.Port.CellsLen(ol) / 24;
        int r = 0;
        while (r < n) {
            int ts = emon.Port.CellsAt(ol, (r * 24) + 5);
            int tl = emon.Port.CellsAt(ol, (r * 24) + 6);
            if ((ts >= 0) && (tl > 0)) {
                HdPriorAdd(pr, ptxt, 2, ts, tl, txt, emon.Port.CellsAt(ol, r * 24) + 1, 800);
            }
            r += 1;
        }
        return n;
    }
    internal static int HdBlank(int c) {
        if ((c == 32) || ((c == 9) || ((c == 160) || (c == 10)))) {
            return 1;
        }
        return 0;
    }
    internal static int HdSameText(emon.Port.Cells a, int a0, int a1, emon.Port.Cells b, int b0, int b1) {
        // Equal as titles: the same code points once blanks are skipped and capitals folded. 1 or 0.
        int i = a0;
        int j = b0;
        while ((i < a1) || (j < b1)) {
            while ((i < a1) && (HdBlank(emon.Port.CellsAt(a, i)) == 1)) {
                i += 1;
            }
            while ((j < b1) && (HdBlank(emon.Port.CellsAt(b, j)) == 1)) {
                j += 1;
            }
            if ((i >= a1) || (j >= b1)) {
                if ((i >= a1) && (j >= b1)) {
                    return 1;
                }
                return 0;
            }
            if (HdFold(emon.Port.CellsAt(a, i)) != HdFold(emon.Port.CellsAt(b, j))) {
                return 0;
            }
            i += 1;
            j += 1;
        }
        return 1;
    }
    internal static int HdLineText(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells tmp, int l) {
        // Append the line's words, one space between two, to `tmp` (and one before the first when tmp is not
        // empty).
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int wn = Evidence.LnGet(ln, l, Evidence.LhCount());
        int k = 0;
        int j = 0;
        while (k < wn) {
            int tl = HdWl(wd, w0 + k);
            if (tl > 0) {
                if (emon.Port.CellsLen(tmp) > 0) {
                    emon.Port.CellsPush(tmp, 32);
                }
                j = 0;
                while (j < tl) {
                    emon.Port.CellsPush(tmp, HdWc(wd, et, w0 + k, j));
                    j += 1;
                }
            }
            k += 1;
        }
        return 0;
    }
    internal static int HdApplyPriors(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells sf, emon.Port.Cells ws, emon.Port.Cells tmp, emon.Port.Cells pr, emon.Port.Cells ptxt, int n) {
        // Match every unit's text to the priors; the best (heaviest) prior of a unit is kept in the unit's
        // fields 13 (level) and 14 (weight). A unit's text is compared whole and without its number.
        int nu = emon.Port.CellsAt(ws, WsVar);
        int np = emon.Port.CellsLen(pr) / 5;
        int u = 0;
        int r = 0;
        int l = 0;
        int found = 0;
        int tl = 0;
        if (np == 0) {
            return 0;
        }
        while (u < nu) {
            emon.Port.CellsDrop(tmp, 0);
            // the unit's lines are consecutive rows of one chain; collect them through the unit id
            l = 0;
            while (l < n) {
                if (Style.StGet(sf, l, Style.SfkUnit()) == u) {
                    HdLineText(wd, ln, et, tmp, l);
                }
                l += 1;
            }
            tl = emon.Port.CellsLen(tmp);
            r = 0;
            while (r < np) {
                int ps = emon.Port.CellsAt(pr, r * 5);
                int pl = emon.Port.CellsAt(pr, (r * 5) + 1);
                int lev = emon.Port.CellsAt(pr, (r * 5) + 2);
                int w = emon.Port.CellsAt(pr, (r * 5) + 4);
                int skip = HdUn(ws, u, 9);
                if (w > HdUn(ws, u, 14)) {
                    found = 0;
                    if (HdSameText(tmp, 0, tl, ptxt, ps, ps + pl) == 1) {
                        found = 1;
                    }
                    if ((found == 0) && (skip > 0)) {
                        if (HdSameText(tmp, skip, tl, ptxt, ps, ps + pl) == 1) {
                            found = 1;
                        }
                    }
                    if (found == 1) {
                        HdUnSet(ws, u, 13, lev);
                        HdUnSet(ws, u, 14, w);
                    }
                }
                r += 1;
            }
            u += 1;
        }
        return 0;
    }
    internal static int HdHk(emon.Port.Cells ws, int c, int f) {
        return emon.Port.CellsAt(ws, (WsHk + (c * HkStride)) + f);
    }
    internal static int HdHkSet(emon.Port.Cells ws, int c, int f, int v) {
        emon.Port.CellsSet(ws, (WsHk + (c * HkStride)) + f, v);
        return 0;
    }
    internal static int HdDkey(int scheme, int depth, int hier) {
        // The numbering key of a unit's class: 0 none, the dotted depth for a hierarchical decimal (a bare `1.`
        // counts as depth 1 only when the document has dotted numbers somewhere), minus the scheme for a flat one.
        if (scheme == 0) {
            return 0;
        }
        if ((scheme == 1) || ((scheme == 6) || (scheme == 7))) {
            if (depth >= 2) {
                return depth;
            }
            if (depth == 1) {
                if (hier == 1) {
                    return 1;
                }
                return 0;
            }
            return 0 - scheme;
        }
        return 0 - scheme;
    }
    internal static int HdHkAdd(emon.Port.Cells ws, int c, int f, int d) {
        int v = HdHk(ws, c, f);
        HdHkSet(ws, c, f, v + d);
        return 0;
    }
    internal static int HdClassFind(emon.Port.Cells ws, int nk, int sclass, int dkey, int ind, int cen) {
        int c = 0;
        while (c < nk) {
            if ((HdHk(ws, c, 0) == sclass) && ((HdHk(ws, c, 1) == dkey) && ((HdHk(ws, c, 2) == ind) && (HdHk(ws, c, 3) == cen)))) {
                return c;
            }
            c += 1;
        }
        return -1;
    }
    internal static int HdProm(emon.Port.Cells sc, int sclass) {
        // How prominent a style class is: the size first, then bold, capitals, italic. Light evidence.
        int bits = Style.ScGet(sc, sclass, Style.SckBits());
        int p = Style.ScGet(sc, sclass, Style.SckBucket()) * 8;
        if ((bits & 1) != 0) {
            p += 4;
        }
        if (Style.ScGet(sc, sclass, Style.SckCaps()) == 1) {
            p += 2;
        }
        if ((bits & 2) != 0) {
            p += 1;
        }
        return p;
    }
    internal static int HdClassify(emon.Port.Cells ln, emon.Port.Cells ws, emon.Port.Cells sf, emon.Port.Cells sc) {
        // Group the units into heading classes (style class, numbering key, indent, centred), merge an unnumbered
        // class into the one numbered class of its own style, and fill each class's counts, prominence, target
        // level and prior. Answers the number of classes.
        int nu = emon.Port.CellsAt(ws, WsVar);
        int hier = 0;
        int u = 0;
        int nk = 0;
        int c = 0;
        int o = 0;
        int hits = 0;
        int hit = 0;
        while (u < nu) {
            int s = HdUn(ws, u, 5);
            if (((s == 1) || ((s == 6) || (s == 7))) && (HdUn(ws, u, 6) >= 2)) {
                hier = 1;
            }
            u += 1;
        }
        emon.Port.CellsSet(ws, WsVar + 2, hier);
        c = 0;
        while (c < (HdKmax * HkStride)) {
            emon.Port.CellsSet(ws, WsHk + c, 0);
            c += 1;
        }
        u = 0;
        while (u < nu) {
            int top = HdUn(ws, u, 0);
            int sclass = Style.StGet(sf, top, Style.SfkClass());
            int cen = Style.StGet(sf, top, Style.SfkCentered());
            int ind = Style.StGet(sf, top, Style.SfkIndent());
            int dk = HdDkey(HdUn(ws, u, 5), HdUn(ws, u, 6), hier);
            if (cen == 1) {
                ind = 0;
            }
            c = HdClassFind(ws, nk, sclass, dk, ind, cen);
            if (c < 0) {
                if (nk < HdKmax) {
                    HdHkSet(ws, nk, 0, sclass);
                    HdHkSet(ws, nk, 1, dk);
                    HdHkSet(ws, nk, 2, ind);
                    HdHkSet(ws, nk, 3, cen);
                    c = nk;
                    nk += 1;
                } else {
                    c = 0;
                    o = 0;
                    while (o < nk) {
                        if (HdHk(ws, o, 0) == sclass) {
                            c = o;
                        }
                        o += 1;
                    }
                }
            }
            HdUnSet(ws, u, 3, c);
            HdHkAdd(ws, c, 4, 1);
            u += 1;
        }
        // an unnumbered class is the numbered class of its own style, when there is exactly one such
        c = 0;
        while (c < nk) {
            if ((HdHk(ws, c, 1) == 0) && (HdHk(ws, c, 4) > 0)) {
                hits = 0;
                hit = -1;
                o = 0;
                while (o < nk) {
                    if ((o != c) && ((HdHk(ws, o, 1) != 0) && ((HdHk(ws, o, 0) == HdHk(ws, c, 0)) && ((HdHk(ws, o, 2) == HdHk(ws, c, 2)) && (HdHk(ws, o, 3) == HdHk(ws, c, 3)))))) {
                        hits += 1;
                        hit = o;
                    }
                    o += 1;
                }
                if (hits == 1) {
                    u = 0;
                    while (u < nu) {
                        if (HdUn(ws, u, 3) == c) {
                            HdUnSet(ws, u, 3, hit);
                        }
                        u += 1;
                    }
                    int moved = HdHk(ws, c, 4);
                    HdHkAdd(ws, hit, 4, moved);
                    HdHkSet(ws, c, 4, 0);
                }
            }
            c += 1;
        }
        // drop the emptied classes: the new index of each old one is kept in WS_BEST
        int w = 0;
        c = 0;
        while (c < nk) {
            if (HdHk(ws, c, 4) > 0) {
                emon.Port.CellsSet(ws, WsBest + c, w);
                o = 0;
                while (o < HkStride) {
                    int cell = HdHk(ws, c, o);
                    HdHkSet(ws, w, o, cell);
                    o += 1;
                }
                w += 1;
            } else {
                emon.Port.CellsSet(ws, WsBest + c, -1);
            }
            c += 1;
        }
        u = 0;
        while (u < nu) {
            int old = HdUn(ws, u, 3);
            int fresh = emon.Port.CellsAt(ws, WsBest + old);
            HdUnSet(ws, u, 3, fresh);
            u += 1;
        }
        nk = w;
        // prominence, target level, prior
        c = 0;
        while (c < nk) {
            int pm = HdProm(sc, HdHk(ws, c, 0));
            int dk = HdHk(ws, c, 1);
            HdHkSet(ws, c, 9, pm);
            HdHkSet(ws, c, 8, 0);
            if (dk > 0) {
                HdHkSet(ws, c, 8, dk);
            }
            HdHkSet(ws, c, 6, 0);
            HdHkSet(ws, c, 7, 0);
            HdHkSet(ws, c, 11, 0);
            c += 1;
        }
        u = 0;
        while (u < nu) {
            if (HdUn(ws, u, 14) > 0) {
                int k = HdUn(ws, u, 3);
                int pw = HdUn(ws, u, 14);
                int plv = HdUn(ws, u, 13);
                HdHkAdd(ws, k, 6, plv * pw);
                HdHkAdd(ws, k, 7, pw);
                HdHkAdd(ws, k, 11, 1);
            }
            u += 1;
        }
        c = 0;
        while (c < nk) {
            if (HdHk(ws, c, 11) > 0) {
                int sw = HdHk(ws, c, 7);
                int sl = HdHk(ws, c, 6);
                int pc = HdHk(ws, c, 11);
                HdHkSet(ws, c, 6, (sl + (sw / 2)) / sw);
                HdHkSet(ws, c, 7, sw / pc);
            }
            c += 1;
        }
        emon.Port.CellsSet(ws, WsVar + 1, nk);
        return nk;
    }
    internal static bool HdBefore(emon.Port.Cells ws, int a, int b) {
        // Does unit a come before unit b in reading order: page, then top of the page down, then left, then
        // the order they were found in. A total order.
        int pa = HdUn(ws, a, 10);
        int pb = HdUn(ws, b, 10);
        int ya = HdUn(ws, a, 11);
        int yb = HdUn(ws, b, 11);
        int xa = HdUn(ws, a, 12);
        int xb = HdUn(ws, b, 12);
        if (pa != pb) {
            return pa < pb;
        }
        if (ya != yb) {
            return ya < yb;
        }
        if (xa != xb) {
            return xa < xb;
        }
        return a < b;
    }
    internal static int HdOrder(emon.Port.Cells ws) {
        // The units in reading order: their indices, pushed after the last unit, insertion sorted. Answers the
        // base of that run (its length is the unit count).
        int nu = emon.Port.CellsAt(ws, WsVar);
        int @base = emon.Port.CellsLen(ws);
        int i = 0;
        int j = 0;
        int v = 0;
        while (i < nu) {
            emon.Port.CellsPush(ws, i);
            i += 1;
        }
        i = 1;
        while (i < nu) {
            v = emon.Port.CellsAt(ws, @base + i);
            j = i - 1;
            while ((j >= 0) && HdBefore(ws, v, emon.Port.CellsAt(ws, @base + j))) {
                emon.Port.CellsSet(ws, @base + (j + 1), emon.Port.CellsAt(ws, @base + j));
                j -= 1;
            }
            emon.Port.CellsSet(ws, @base + (j + 1), v);
            i += 1;
        }
        return @base;
    }
    internal static int HdMatrices(emon.Port.Cells ws, int @base, int nk) {
        // From the sequence of the document's headings: T[a][b], how often a class b follows a class a; O[a][b],
        // how often a class a occurs before the first occurrence of b; each class's first position; the class
        // the document starts with; the deepest numbering target.
        int nu = emon.Port.CellsAt(ws, WsVar);
        int i = 0;
        int b = 0;
        int mt = 0;
        while (i < 256) {
            emon.Port.CellsSet(ws, WsT + i, 0);
            emon.Port.CellsSet(ws, WsO + i, 0);
            i += 1;
        }
        i = 0;
        while (i < nk) {
            HdHkSet(ws, i, 5, 1000000000);
            if (HdHk(ws, i, 8) > mt) {
                mt = HdHk(ws, i, 8);
            }
            i += 1;
        }
        emon.Port.CellsSet(ws, WsVar + 4, mt);
        i = 0;
        while (i < nu) {
            int c = HdUn(ws, emon.Port.CellsAt(ws, @base + i), 3);
            if (HdHk(ws, c, 5) > i) {
                HdHkSet(ws, c, 5, i);
            }
            i += 1;
        }
        i = 0;
        while (i < nu) {
            int c = HdUn(ws, emon.Port.CellsAt(ws, @base + i), 3);
            b = 0;
            while (b < nk) {
                if ((b != c) && (HdHk(ws, b, 5) > i)) {
                    emon.Port.CellsSet(ws, (WsO + (c * HdKmax)) + b, emon.Port.CellsAt(ws, (WsO + (c * HdKmax)) + b) + 1);
                }
                b += 1;
            }
            if (i > 0) {
                int pc = HdUn(ws, emon.Port.CellsAt(ws, @base + (i - 1)), 3);
                if (pc != c) {
                    emon.Port.CellsSet(ws, (WsT + (pc * HdKmax)) + c, emon.Port.CellsAt(ws, (WsT + (pc * HdKmax)) + c) + 1);
                }
            }
            if (i == 0) {
                emon.Port.CellsSet(ws, WsVar + 3, c);
            }
            i += 1;
        }
        return 0;
    }
    internal static int HdEval(emon.Port.Cells ws, int nk) {
        // The penalty of the levels in ws[WS_LV..] (D018). Integer, deterministic.
        int pen = 0;
        int a = 0;
        int b = 0;
        while (a < nk) {
            int la = emon.Port.CellsAt(ws, WsLv + a);
            int tg = HdHk(ws, a, 8);
            if (tg > 0) {
                pen += WDepth * HdAbs(la - tg);
            }
            if (HdHk(ws, a, 11) > 0) {
                pen += ((WPrior * HdHk(ws, a, 7)) * HdAbs(la - HdHk(ws, a, 6))) / 1000;
            }
            b = 0;
            while (b < nk) {
                if (a != b) {
                    int lb = emon.Port.CellsAt(ws, WsLv + b);
                    if (la > lb) {
                        pen += WOrphan * emon.Port.CellsAt(ws, (WsO + (a * HdKmax)) + b);
                        if (HdHk(ws, a, 9) > HdHk(ws, b, 9)) {
                            pen += WProm;
                        }
                    }
                    // two classes of one style that differ only in alignment or indent are twins: they want one level
                    if ((HdHk(ws, a, 0) == HdHk(ws, b, 0)) && (HdHk(ws, a, 1) == HdHk(ws, b, 1))) {
                        if (la != lb) {
                            pen += WTwin;
                        }
                    } else if ((la == lb) && (a < b)) {
                        pen += WSame;
                    }
                    if ((lb - la) > 1) {
                        pen += (WSkip * ((lb - la) - 1)) * emon.Port.CellsAt(ws, (WsT + (a * HdKmax)) + b);
                    }
                }
                b += 1;
            }
            a += 1;
        }
        int lf = emon.Port.CellsAt(ws, WsLv + emon.Port.CellsAt(ws, WsVar + 3));
        if (lf > 1) {
            pen += WSkip * (lf - 1);
        }
        return pen;
    }
    internal static int HdSearch(emon.Port.Cells ws, int nk) {
        // The levels that minimise `hd-eval`: every assignment up to HD_EXHAUSTIVE classes (the first found
        // wins a tie), coordinate descent beyond. The result is each class's field 10.
        int mt = emon.Port.CellsAt(ws, WsVar + 4);
        int lmax = nk;
        int best = 2000000000;
        int i = 0;
        int more = 1;
        int carry = 0;
        int pen = 0;
        int c = 0;
        int lv = 0;
        int keep = 0;
        int sweeps = 0;
        int changed = 1;
        if (mt > lmax) {
            lmax = mt;
        }
        if (lmax > 12) {
            lmax = 12;
        }
        if (nk <= HdExhaustive) {
            i = 0;
            while (i < nk) {
                emon.Port.CellsSet(ws, WsLv + i, 1);
                i += 1;
            }
            while (more == 1) {
                pen = HdEval(ws, nk);
                if (pen < best) {
                    best = pen;
                    i = 0;
                    while (i < nk) {
                        emon.Port.CellsSet(ws, WsBest + i, emon.Port.CellsAt(ws, WsLv + i));
                        i += 1;
                    }
                }
                i = 0;
                carry = 1;
                while ((carry == 1) && (i < nk)) {
                    emon.Port.CellsSet(ws, WsLv + i, emon.Port.CellsAt(ws, WsLv + i) + 1);
                    if (emon.Port.CellsAt(ws, WsLv + i) > lmax) {
                        emon.Port.CellsSet(ws, WsLv + i, 1);
                        i += 1;
                    } else {
                        carry = 0;
                    }
                }
                if (carry == 1) {
                    more = 0;
                }
            }
        } else {
            // start from the first-occurrence order (or the numbering's own level), then improve one class at a time
            c = 0;
            while (c < nk) {
                lv = 1;
                i = 0;
                while (i < nk) {
                    if (HdHk(ws, i, 5) < HdHk(ws, c, 5)) {
                        lv += 1;
                    }
                    i += 1;
                }
                if (HdHk(ws, c, 8) > 0) {
                    lv = HdHk(ws, c, 8);
                }
                if (lv > lmax) {
                    lv = lmax;
                }
                emon.Port.CellsSet(ws, WsLv + c, lv);
                c += 1;
            }
            best = HdEval(ws, nk);
            while ((changed == 1) && (sweeps < 30)) {
                changed = 0;
                c = 0;
                while (c < nk) {
                    keep = emon.Port.CellsAt(ws, WsLv + c);
                    lv = 1;
                    while (lv <= lmax) {
                        emon.Port.CellsSet(ws, WsLv + c, lv);
                        pen = HdEval(ws, nk);
                        if (pen < best) {
                            best = pen;
                            keep = lv;
                            changed = 1;
                        }
                        lv += 1;
                    }
                    emon.Port.CellsSet(ws, WsLv + c, keep);
                    c += 1;
                }
                sweeps += 1;
            }
            i = 0;
            while (i < nk) {
                emon.Port.CellsSet(ws, WsBest + i, emon.Port.CellsAt(ws, WsLv + i));
                i += 1;
            }
        }
        i = 0;
        while (i < nk) {
            HdHkSet(ws, i, 10, emon.Port.CellsAt(ws, WsBest + i));
            i += 1;
        }
        return best;
    }
    internal static int HdEmit(emon.Port.Cells ln, emon.Port.Cells hc, emon.Port.Cells ws, emon.Port.Cells sf, int n) {
        // One row of `hc` for every line of every kept unit: the level of its class and, on the unit's first
        // line, where the number is, how much to skip, the scheme, and the start flag.
        int l = 0;
        while (l < n) {
            int u = Style.StGet(sf, l, Style.SfkUnit());
            if (u >= 0) {
                int hcl = HdUn(ws, u, 3);
                int lev = HdHk(ws, hcl, 10);
                int at = HcHdr + (l * HcStride);
                emon.Port.CellsSet(hc, at, lev);
                if (l == HdUn(ws, u, 0)) {
                    emon.Port.CellsSet(hc, at + 1, HdUn(ws, u, 7));
                    emon.Port.CellsSet(hc, at + 2, HdUn(ws, u, 8));
                    emon.Port.CellsSet(hc, at + 3, HdUn(ws, u, 9));
                    emon.Port.CellsSet(hc, at + 4, HdUn(ws, u, 5));
                    emon.Port.CellsSet(hc, at + 5, 3);
                } else {
                    emon.Port.CellsSet(hc, at + 5, 2);
                }
            }
            l += 1;
        }
        return 0;
    }
    public static int HdAnalyze(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells sf, emon.Port.Cells sc, emon.Port.Cells hc, emon.Port.Cells ws, emon.Port.Cells tmp, emon.Port.Cells pr, emon.Port.Cells ptxt) {
        // Decide which lines are headings and at what level. `sf`, `sc`, `ws`, `tmp` are scratch, `hc` the answer
        // (emptied first); `pr` and `ptxt` the priors (`hd-prior-add`), empty when there are none. Answers the
        // number of headings found.
        int n = Evidence.LnCount(ln);
        int l = 0;
        int nu = 0;
        int nk = 0;
        int @base = 0;
        Style.StBuild(wd, ln, et, gl, sf, sc, tmp);
        emon.Port.CellsDrop(hc, 0);
        while (l < HcHdr) {
            emon.Port.CellsPush(hc, 0);
            l += 1;
        }
        emon.Port.CellsSet(hc, 0, n);
        l = 0;
        while (l < (n * HcStride)) {
            emon.Port.CellsPush(hc, 0);
            l += 1;
        }
        emon.Port.CellsDrop(ws, 0);
        l = 0;
        while (l < WsU) {
            emon.Port.CellsPush(ws, 0);
            l += 1;
        }
        if (Style.StHget(sf, Style.SfhBody()) < 0) {
            return 0;
        }
        l = 0;
        while (l < n) {
            Style.StSet(sf, l, Style.SfkUnit(), -1);
            Style.StSet(sf, l, Style.SfkHead(), 0);
            l += 1;
        }
        l = 0;
        while (l < n) {
            HdHeadish(wd, ln, et, sf, sc, ws, l);
            l += 1;
        }
        nu = HdCollect(wd, ln, et, ws, sf, sc, n);
        if (nu > 0) {
            nu = HdDropLone(ws, sf, n);
        }
        if (nu == 0) {
            return 0;
        }
        HdApplyPriors(wd, ln, et, sf, ws, tmp, pr, ptxt, n);
        nk = HdClassify(ln, ws, sf, sc);
        @base = HdOrder(ws);
        HdMatrices(ws, @base, nk);
        HdSearch(ws, nk);
        HdEmit(ln, hc, ws, sf, n);
        return nu;
    }
}
